The disagreements fit y = min(f(a), g(b)) for skill 0 and y = max(f(a), h(b)) for skill 2, because rows only change the cells where the column class exceeds or falls below the row class. I read per-value tables for several two-argument forms with two counting passes over the network's own table, and compare fit for all four skills.
```python
import numpy as np
T=np.load("Tavg.npy")
ops={'min':np.minimum,'max':np.maximum,'sumclip':lambda x,y:np.clip(x+y,0,7),'summod':lambda x,y:(x+y)%8,'xor':lambda x,y:x^y,'or':lambda x,y:x|y,'and':lambda x,y:x&y,'submod':lambda x,y:(x-y)%8,'absdiff':lambda x,y:np.abs(x-y)}
vals=np.arange(8)
res={}
def passes(t,op,f,g,n=3):
    for _ in range(n):
        # choose f(a) by counting matches over the row given g, then g(b) given f
        f=np.array([vals[np.argmax([(op(np.full(32,c),g)==t[i]).sum() for c in vals])] for i in range(32)])
        g=np.array([vals[np.argmax([(op(f,np.full(32,c))==t[:,j]).sum() for c in vals])] for j in range(32)])
    return f,g
for s in range(4):
    t=T[:,:,s]; out={}
    for name,op in ops.items():
        bestacc=-1
        for init in ('med','mean0','half'):
            if init=='med': f0=np.median(t,axis=1).astype(int); g0=np.median(t,axis=0).astype(int)
            elif init=='mean0': f0=np.floor(t.mean(1)-t.mean()+2).clip(0,7).astype(int); g0=np.floor(t.mean(0)-t.mean()+2).clip(0,7).astype(int)
            else: f0=(t.max(1)//2).astype(int); g0=(t.max(0)//2).astype(int)
            f,g=passes(t,op,f0,g0)
            acc=(op(f[:,None],g[None,:])==t).mean()
            if acc>bestacc: bestacc=acc; best=(f,g)
        out[name]=round(float(bestacc),3); res[(s,name)]=best
    print('skill',s,out)
for key in [(0,'min'),(2,'max'),(1,'sumclip')]:
    f,g=res[key]; print(key,'f',f.tolist(),'g',g.tolist())
np.save("res.npy",np.array([[k[0],k[1],v[0],v[1]] for k,v in res.items()],dtype=object),allow_pickle=True)
# skill 3 row-pair analysis
t=T[:,:,3]
conc=np.zeros((32,32)); dd=np.zeros((32,32),int)
for i in range(32):
    for j in range(32):
        c=np.bincount((t[i]-t[j])%8,minlength=8); conc[i,j]=c.max()/32; dd[i,j]=c.argmax()
np.fill_diagonal(conc,0); print('skill3 conc pctiles',np.round(np.percentile(conc,[50,90,99,100]),2).tolist())
